        Map<String, String> values = new HashMap<String, String>();
        String table = "STATIONARY_WATER:WATER|FLOWING_WATER:WATER|STATIONARY_LAVA:LAVA|FLOWING_LAVA:LAVA|PISTON_STICKY_BASE:STICKY_PISTON|WEB:COBWEB|PISTON_BASE:PISTON|PISTON_EXTENSION:PISTON_HEAD|PISTON_MOVING_PIECE:MOVING_PISTON|YELLOW_FLOWER:DANDELION|BRICK:BRICKS|WOOD_STAIRS:OAK_STAIRS|WORKBENCH:CRAFTING_TABLE|CROPS:WHEAT|SOIL:FARMLAND|BURNING_FURNACE:FURNACE|LIT_FURNACE:FURNACE|SIGN_POST:OAK_SIGN|STANDING_SIGN:OAK_SIGN|WALL_SIGN:OAK_WALL_SIGN|SIGN:OAK_SIGN|WOODEN_DOOR:OAK_DOOR|WOOD_DOOR:OAK_DOOR|RAILS:RAIL|STONE_PLATE:STONE_PRESSURE_PLATE|IRON_DOOR_BLOCK:IRON_DOOR|WOOD_PLATE:OAK_PRESSURE_PLATE|GLOWING_REDSTONE_ORE:REDSTONE_ORE|LIT_REDSTONE_ORE:REDSTONE_ORE|REDSTONE_TORCH_OFF:REDSTONE_TORCH|REDSTONE_TORCH_ON:REDSTONE_TORCH|UNLIT_REDSTONE_TORCH:REDSTONE_TORCH|SUGAR_CANE_BLOCK:SUGAR_CANE|REEDS:SUGAR_CANE|FENCE:OAK_FENCE|PORTAL:NETHER_PORTAL|CAKE_BLOCK:CAKE|DIODE_BLOCK_OFF:REPEATER|DIODE_BLOCK_ON:REPEATER|DIODE:REPEATER|UNPOWERED_REPEATER:REPEATER|POWERED_REPEATER:REPEATER|TRAP_DOOR:OAK_TRAPDOOR|TRAPDOOR:OAK_TRAPDOOR|HUGE_MUSHROOM_1:BROWN_MUSHROOM_BLOCK|HUGE_MUSHROOM_2:RED_MUSHROOM_BLOCK|IRON_FENCE:IRON_BARS|THIN_GLASS:GLASS_PANE|MELON_BLOCK:MELON|FENCE_GATE:OAK_FENCE_GATE|SMOOTH_STAIRS:STONE_BRICK_STAIRS|MYCEL:MYCELIUM|WATER_LILY:LILY_PAD|WATERLILY:LILY_PAD|NETHER_BRICK:NETHER_BRICKS|NETHER_FENCE:NETHER_BRICK_FENCE|NETHER_WARTS:NETHER_WART|ENDER_PORTAL:END_PORTAL|ENDER_PORTAL_FRAME:END_PORTAL_FRAME|ENDER_STONE:END_STONE|SPRUCE_WOOD_STAIRS:SPRUCE_STAIRS|BIRCH_WOOD_STAIRS:BIRCH_STAIRS|JUNGLE_WOOD_STAIRS:JUNGLE_STAIRS|COMMAND:COMMAND_BLOCK|GOLD_PLATE:LIGHT_WEIGHTED_PRESSURE_PLATE|IRON_PLATE:HEAVY_WEIGHTED_PRESSURE_PLATE|REDSTONE_COMPARATOR_OFF:COMPARATOR|REDSTONE_COMPARATOR_ON:COMPARATOR|REDSTONE_COMPARATOR:COMPARATOR|UNPOWERED_COMPARATOR:COMPARATOR|POWERED_COMPARATOR:COMPARATOR|WOOD_BUTTON:OAK_BUTTON|WOODEN_BUTTON:OAK_BUTTON|QUARTZ_ORE:NETHER_QUARTZ_ORE|HARD_CLAY:TERRACOTTA|HARDENED_CLAY:TERRACOTTA|STANDING_BANNER:WHITE_BANNER|WALL_BANNER:WHITE_WALL_BANNER|DAYLIGHT_DETECTOR_INVERTED:DAYLIGHT_DETECTOR|PURPUR_DOUBLE_SLAB:PURPUR_SLAB|END_BRICKS:END_STONE_BRICKS|BEETROOT_BLOCK:BEETROOTS|GRASS_PATH:DIRT_PATH|COMMAND_REPEATING:REPEATING_COMMAND_BLOCK|COMMAND_CHAIN:CHAIN_COMMAND_BLOCK|MAGMA:MAGMA_BLOCK|RED_NETHER_BRICK:RED_NETHER_BRICKS|WOOD_SWORD:WOODEN_SWORD|WOOD_PICKAXE:WOODEN_PICKAXE|WOOD_AXE:WOODEN_AXE|WOOD_HOE:WOODEN_HOE|MUSHROOM_SOUP:MUSHROOM_STEW|GOLD_SWORD:GOLDEN_SWORD|GOLD_PICKAXE:GOLDEN_PICKAXE|GOLD_AXE:GOLDEN_AXE|GOLD_HOE:GOLDEN_HOE|GOLD_HELMET:GOLDEN_HELMET|GOLD_CHESTPLATE:GOLDEN_CHESTPLATE|GOLD_LEGGINGS:GOLDEN_LEGGINGS|GOLD_BOOTS:GOLDEN_BOOTS|SULPHUR:GUNPOWDER|SEEDS:WHEAT_SEEDS|PORK:PORKCHOP|GRILLED_PORK:COOKED_PORKCHOP|SNOW_BALL:SNOWBALL|BOAT:OAK_BOAT|CLAY_BRICK:BRICK|STORAGE_MINECART:CHEST_MINECART|POWERED_MINECART:FURNACE_MINECART|WATCH:CLOCK|MAP:FILLED_MAP|EMPTY_MAP:MAP|MELON:MELON_SLICE|RAW_BEEF:BEEF|RAW_CHICKEN:CHICKEN|NETHER_STALK:NETHER_WART|BREWING_STAND_ITEM:BREWING_STAND|CAULDRON_ITEM:CAULDRON|EYE_OF_ENDER:ENDER_EYE|SPECKLED_MELON:GLISTERING_MELON_SLICE|EXP_BOTTLE:EXPERIENCE_BOTTLE|FIREBALL:FIRE_CHARGE|BOOK_AND_QUILL:WRITABLE_BOOK|FLOWER_POT_ITEM:FLOWER_POT|CARROT_ITEM:CARROT|POTATO_ITEM:POTATO|CARROT_STICK:CARROT_ON_A_STICK|FIREWORK:FIREWORK_ROCKET|FIREWORKS:FIREWORK_ROCKET|FIREWORK_CHARGE:FIREWORK_STAR|NETHER_BRICK_ITEM:NETHER_BRICK|EXPLOSIVE_MINECART:TNT_MINECART|IRON_BARDING:IRON_HORSE_ARMOR|GOLD_BARDING:GOLDEN_HORSE_ARMOR|DIAMOND_BARDING:DIAMOND_HORSE_ARMOR|LEASH:LEAD|COMMAND_MINECART:COMMAND_BLOCK_MINECART|SPRUCE_DOOR_ITEM:SPRUCE_DOOR|BIRCH_DOOR_ITEM:BIRCH_DOOR|JUNGLE_DOOR_ITEM:JUNGLE_DOOR|ACACIA_DOOR_ITEM:ACACIA_DOOR|DARK_OAK_DOOR_ITEM:DARK_OAK_DOOR|CHORUS_FRUIT_POPPED:POPPED_CHORUS_FRUIT|BOAT_SPRUCE:SPRUCE_BOAT|BOAT_BIRCH:BIRCH_BOAT|BOAT_JUNGLE:JUNGLE_BOAT|BOAT_ACACIA:ACACIA_BOAT|BOAT_DARK_OAK:DARK_OAK_BOAT|TOTEM:TOTEM_OF_UNDYING|GOLD_RECORD:MUSIC_DISC_13|GREEN_RECORD:MUSIC_DISC_CAT|RECORD_3:MUSIC_DISC_BLOCKS|RECORD_4:MUSIC_DISC_CHIRP|RECORD_5:MUSIC_DISC_FAR|RECORD_6:MUSIC_DISC_MALL|RECORD_7:MUSIC_DISC_MELLOHI|RECORD_8:MUSIC_DISC_STAL|RECORD_9:MUSIC_DISC_STRAD|RECORD_10:MUSIC_DISC_WARD|RECORD_11:MUSIC_DISC_11|RECORD_12:MUSIC_DISC_WAIT";
