        values.put("REDSTONE_LAMP_ON", "REDSTONE_LAMP");
        values.put("DRAGONS_BREATH", "DRAGON_BREATH");
        values.put("DEADBUSH", "DEAD_BUSH");
        values.put("GOLDEN_RAIL", "POWERED_RAIL");
